mapper.select:
SELECT * FROM tenant_provision_task
WHERE id = #{id}
  AND deleted_at IS NULL

SELECT * FROM tenant_provision_task
WHERE tenant_id = #{tenantId}
  AND task_key = #{taskKey}
  AND deleted_at IS NULL
ORDER BY id DESC
LIMIT 1

SELECT * FROM tenant_provision_task
WHERE task_key = #{taskKey}
  AND idempotency_key = #{idempotencyKey}
  AND deleted_at IS NULL
ORDER BY id DESC
LIMIT 1
